  def caveats
    <<~EOS
      Para activar la función pt, añade a ~/.zshrc:
        eval "$(#{opt_bin}/projectory init zsh)"
      o, en bash, a ~/.bashrc:
        eval "$(#{opt_bin}/projectory init bash)"

