  test do
    assert_match version.to_s, shell_output("#{bin}/projectory --version")

    ENV["PROJECTORY_DATA_DIR"] = (testpath/"data").to_s
    ENV["PROJECTORY_CONFIG_DIR"] = (testpath/"config").to_s
    (testpath/"demo").mkpath
